param([string]$MigrationPath="$PSScriptRoot/../../sql/updates/world/2026_10_27_04_lights_wrath_takeover.sql",[switch]$VerifyLive)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/lights-wrath-takeover-data"
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories $out -Test {
 $migration=Get-Content $MigrationPath -Raw
 $native=Get-Content "$PSScriptRoot/LightsWrathTakeoverOriginal.json" -Raw|ConvertFrom-Json
 $filters=[ordered]@{creature_template='entry IN(104985,104986)';creature='id=104985';smart_scripts='entryorguid IN(104985,-370524,104986) OR(action_type=80 AND action_param1=104985)';npc_spellclick_spells='npc_entry=104985 OR spell_id IN(207949,207996)';conditions='(SourceTypeOrReferenceId=17 AND SourceEntry IN(207949,207996)) OR(SourceTypeOrReferenceId=18 AND SourceGroup=104985) OR(SourceTypeOrReferenceId=22 AND SourceEntry IN(104985,-370524))';spell_script_names='ABS(spell_id) IN(207949,207996)'}
 $setup='';foreach($t in $filters.Keys){$setup+="CREATE TEMPORARY TABLE saved_$t LIKE $t;INSERT INTO saved_$t SELECT * FROM $t WHERE $($filters[$t]);CREATE TEMPORARY TABLE $t LIKE saved_$t;INSERT INTO $t SELECT * FROM saved_$t;`n"}
 $setup+="UPDATE creature_template SET AIName='SmartAI',ScriptName='' WHERE entry=104985;DELETE FROM smart_scripts WHERE entryorguid=104985 AND source_type IN(0,9);DELETE FROM spell_script_names WHERE (spell_id=207949 AND ScriptName IN('spell_lights_wrath_control_request','spell_lights_wrath_control_channel')) OR(spell_id=207996 AND ScriptName='spell_lights_wrath_control_result');"
 $values=@();foreach($row in $native.rows){$cell=@();foreach($field in $native.fields){$value=$row.$field;if($value -is [string]){$cell+="'"+$value.Replace("'","''")+"'"}else{$cell+=[Convert]::ToString($value,[Globalization.CultureInfo]::InvariantCulture)}};$values+='('+($cell -join ',')+')'}
 $setup+='INSERT INTO smart_scripts('+($native.fields -join ',')+') VALUES'+($values -join ',')+';'
 function Snapshot([string]$label){($filters.Keys|ForEach-Object {"SELECT '$label-$_',a.* FROM $_ a;"}) -join "`n"}
 function Signature($rows,[string]$label){(@($rows|Where-Object {$_ -like "$label`t*"}|ForEach-Object {$_.Substring($label.Length+1)}|Sort-Object -CaseSensitive)) -join "`n"}
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 function Query([string]$sql,[switch]$Expected){$prior=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$db[3];$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names --force 2> "$out/sql-stderr.txt");$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior};$err=Get-Content "$out/sql-stderr.txt" -Raw;if($Expected){if($err -notmatch '1644 \(45000\)' -or @($err -split "`n"|Where-Object {$_ -match '^ERROR '}).Count -ne 1){throw 'Expected takeover refusal missing'}}elseif($code -or $err){throw 'Takeover TEMP/read-only query failed'};$rows}
 $rows=Query "$setup`n$migration`n$(Snapshot 'first')`n$migration`n$(Snapshot 'second')`nSELECT 'legacy',COUNT(*) FROM smart_scripts WHERE entryorguid=104985 AND source_type IN(0,9);SELECT 'bindings',COUNT(*) FROM spell_script_names WHERE ABS(spell_id) IN(207949,207996);"
 foreach($t in $filters.Keys){if((Signature $rows "first-$t") -cne (Signature $rows "second-$t")){throw 'Takeover migration not idempotent'}}
 foreach($e in @("legacy`t0","bindings`t3")){if($rows -notcontains $e){throw 'Missing replacement bindings/legacy removal'}}
 foreach($change in @("UPDATE creature_template SET ScriptName='custom' WHERE entry=104985;",'UPDATE creature_template SET npcflag=0 WHERE entry=104985;','UPDATE smart_scripts SET action_param4=1 WHERE entryorguid=104985 AND source_type=9 AND id=2;','UPDATE smart_scripts SET event_param1=29999 WHERE entryorguid=104985 AND source_type=9 AND id=0;',"UPDATE smart_scripts SET comment='custom' WHERE entryorguid=104985 AND source_type=0 AND id=0;",'UPDATE smart_scripts SET action_param3=0 WHERE entryorguid=104985 AND source_type=9 AND id=2;','DELETE FROM creature WHERE id=104985;','UPDATE creature SET map=1 WHERE id=104985;',"INSERT INTO smart_scripts(entryorguid,source_type,id,event_type,action_type,comment) VALUES(-370524,0,0,73,41,'custom spawn');",'UPDATE npc_spellclick_spells SET cast_flags=3 WHERE npc_entry=104985;',"INSERT INTO spell_script_names VALUES(207996,'custom');","INSERT INTO conditions(SourceTypeOrReferenceId,SourceEntry,ConditionTypeOrReference,ConditionValue1,Comment) VALUES(17,207996,15,1,'custom');")){
  $r=Query "$setup`n$change`n$(Snapshot 'before')`n$migration`n$(Snapshot 'after')" -Expected
  foreach($t in $filters.Keys){if((Signature $r "before-$t") -cne (Signature $r "after-$t")){throw 'Refused takeover migration changed native/custom data'}}
 }
 if($VerifyLive){
  $sha=[Security.Cryptography.SHA1]::Create();try{$hash=[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(([IO.File]::ReadAllText((Resolve-Path $MigrationPath))).Replace("`r`n","`n")))).Replace('-','')}finally{$sha.Dispose()}
  $live=Query "SET SESSION TRANSACTION READ ONLY;SELECT 'update',hash,state FROM updates WHERE name='2026_10_27_04_lights_wrath_takeover.sql';SELECT 'template',AIName,ScriptName FROM creature_template WHERE entry=104985;SELECT 'legacy',COUNT(*) FROM smart_scripts WHERE entryorguid=104985 AND source_type IN(0,9);SELECT 'binding',spell_id,ScriptName FROM spell_script_names WHERE ABS(spell_id) IN(207949,207996);"
  foreach($e in @("update`t$hash`tRELEASED","template`t`tnpc_lights_wrath_takeover","legacy`t0","binding`t207949`tspell_lights_wrath_control_request","binding`t207949`tspell_lights_wrath_control_channel","binding`t207996`tspell_lights_wrath_control_result")){if($live -notcontains $e){throw 'Live takeover readback/hash differs'}}
 }
 'PASS complete31-field native graph signature/pinned native fixture, TEMP twice/three spell bindings and twelve exact custom refusals; all six tables unchanged on refusal. No live data/character mutation in test.'
}
